#!/usr/bin/env python3
"""Independent closure checks on the frozen denominator, native bounds, render pixels and immutable payloads."""
import collections,datetime,hashlib,json,re,sys
from pathlib import Path
import pymupdf as fitz
from PIL import Image,ImageStat
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main():
 baseline=json.loads((OUT/'baseline-records.json').read_text());inventory=json.loads((OUT/'native-inventory.json').read_text());proposals=json.loads((OUT/'proposals.json').read_text());renders=json.loads((OUT/'render-inventory.json').read_text());records={i['id']:i for s in baseline['sources'] for i in s['records']};render_by={i['id']:i for i in renders['records']};by_id={r['id']:r for r in proposals['records']};assert len(records)==len(by_id)==394 and records.keys()==by_id.keys();assert len(render_by)==394;geometry=[];regressions=[];overrides={};pending=[]
 for group in baseline['sources']:
  source=group['source'];sid=group['source_id'];assert sha(ROOT/source['local_path'])==source['sha256'];assert sha(ROOT/group['cache'])==group['cache_sha256'],'The frozen producer cache changed during audit'
  anchors={p['page']:p['anchors'] for s in inventory['sources'] if s['source_id']==sid for p in s['pages_with_codes']}
  overrides[sid]={'artifact_sha256':source['sha256'],'edition':source.get('edition'),'records':{}}
  with fitz.open(ROOT/source['local_path']) as doc:
   for item in group['records']:
    proposal=by_id[item['id']];assert proposal['immutable_fields_preserved'];assert proposal['code']==item['code'];assert proposal['canonical_text_sha256']==hashlib.sha256(item['text'].encode()).hexdigest();assert proposal['source_sha256']==source['sha256'];assert proposal['full_crop_word_tokens_equal'] is True,'Full evidence crop contains changed or extra word tokens'
    text=proposal['proposed_evidence'][1];code=proposal['proposed_evidence'][0];page=text['page'];box=fitz.Rect(text['bbox']);assert page==item['evidence'][0]['page']==code['page'];assert fitz.Rect(doc[page-1].rect).contains(box)
    foreign=[a for a in anchors[page] if a['code']!=item['code'] and box.contains(fitz.Point((a['bbox'][0]+a['bbox'][2])/2,(a['bbox'][1]+a['bbox'][3])/2))];assert not foreign, 'Evidence crosses an unrelated code cell'
    target=[a for a in anchors[page] if a['code']==item['code']];assert len(target)==1;assert fitz.Rect(code['bbox']).contains(fitz.Rect(target[0]['bbox']))
    render=render_by[item['id']];file=ROOT/render['path'];assert sha(file)==render['png_sha256'];image=Image.open(file).convert('RGB');assert image.size==(render['width'],render['height']);assert min(image.size)>10;assert max(ImageStat.Stat(image).stddev)>5,'Blank/empty render'
    geometry.append({'id':item['id'],'page':page,'text_bbox':text['bbox'],'code_bbox':code['bbox'],'unrelated_code_cells_in_bbox':0,'full_crop_word_tokens_equal':True,'native_source_sha256':source['sha256'],'render_sha256':render['png_sha256'],'nonblank_render':True,'multipage_required':False,'scope':'Whole primary paragraph/cell is on this physical page; retained original upstream locator. Native block splits and code-column bounds prevent adjacent year/object/competency cells from being imported.'})
    if proposal['strict_current_checker_passed']:overrides[sid]['records'][item['id']]={'expected_code':item['code'],'canonical_text_sha256':proposal['canonical_text_sha256'],'evidence':proposal['proposed_evidence'],**({'primary_typographic_equivalence':proposal['primary_typographic_equivalence']} if proposal['primary_typographic_equivalence'] else {}),'verification':{'actor_type':'automated','actor_id':'codex-independent-br-fidelity-auditor','method':'independent native code inventory + full primary cell word tokens + exact current literal checker + rawdict/trace + nonblank primary crop','proof_path':'docs/evidence/source-audit-br-fidelity/proposals.json','proof_sha256':sha(OUT/'proposals.json')}}
    else:pending.append({'id':item['id'],'code':item['code'],'source_id':sid,'page':page,'reason':proposal['classification'],'canonical_text':item['text'],'primary_text':proposal['raw_primary_excerpt'],'difference':'Primary uses U+2013 EN DASH, reused CC-BY canonical record uses U+002D HYPHEN-MINUS. Word sequence unchanged. Existing strict checker intentionally left unchanged and still returns false. No override approved.'})
   for item in group['extra_immutable_regressions']:
    assert item['id']=='ca:br-bncc-computacao-2022:EF05CO11';assert item['code']=='EF05CO011' and item['code_aliases']==['EF05CO11'];page=doc[35];printed=page.search_for('EF05CO011');assert len(printed)==1;regressions.append({'id':item['id'],'code':item['code'],'code_aliases':item['code_aliases'],'page':36,'literal_code_bbox':list(printed[0]),'text_sha256':hashlib.sha256(item['text'].encode()).hexdigest(),'identity_preserved':True,'literal_printed_code_verified':True})
 stamp=datetime.datetime.now(datetime.timezone.utc).isoformat();output={'actor_type':'automated','actor_id':'codex-independent-br-fidelity-auditor','generated_at':stamp,'denominator':394,'verified':len(geometry),'strict_current_checker_passed':386,'pending_typographic':len(pending),'checks':{'exact_baseline_id_set':True,'immutable_ids_codes_texts_sources_aliases_preserved':True,'source_PDF_and_cache_hashes_unchanged':True,'full_primary_cell_word_tokens_equal':True,'all_primary_regions_inside_page':True,'no_unrelated_code_cell_in_evidence_bbox':True,'all_394_actual_primary_crops_rendered_nonblank':True,'upstream_physical_pages_retained':True,'no_paragraph_crosses_page_boundary':True},'identity_regressions':regressions,'geometry':geometry,'pending':pending,'publication_modified':False,'checker_modified':False,'national_completeness_asserted':False};(OUT/'verification.json').write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n');(OUT/'locator-overrides.json').write_text(json.dumps({'actor_type':'automated','generated_at':stamp,'denominator':394,'approved_records':386,'pending_records':pending,'verification_sha256':sha(OUT/'verification.json'),'immutable_contract':'Only evidence and explicitly recorded existing-policy typography proof may be applied; reject any source SHA/id/code/text hash mismatch. No code/ID/canonical text/alias/position/parent update. Do not treat remaining eight as passed.','sources':overrides},ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in output.items() if k not in ('geometry','pending')},ensure_ascii=False))
if __name__=='__main__':main()
